package it.comune.trieste.ouf.udp;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Types;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SpatialMaterializer {
  private final JdbcClient db;private final ObjectMapper json;
  public SpatialMaterializer(JdbcClient db,ObjectMapper json){this.db=db;this.json=json;}

  @Transactional public Result materialize(String handoffId,UUID sourceObjectId,Map<String,Object> handoff,UdpPorts.SpatialProfile profile){
    Map<String,Object> payload=HandoffIntakeService.object(handoff,"canonicalPayload");Object raw=payload.get(profile.geometry().sourceField());if(!(raw instanceof Map<?,?> envelope)){return new Result(false,0,0);}
    String crs=Objects.toString(envelope.get("crs"),"");if(crs.isBlank()){issue(handoffId,sourceObjectId,null,"SPATIAL_CRS_REQUIRED",List.of(),Map.of("policyRef",profile.policyRef()));return new Result(false,0,1);}if(!crs.equals(profile.geometry().expectedSourceCrs())){issue(handoffId,sourceObjectId,null,"SPATIAL_CRS_MISMATCH",List.of(),Map.of("declaredCrs",crs,"expectedCrs",profile.geometry().expectedSourceCrs(),"policyRef",profile.policyRef()));return new Result(false,0,1);}
    if(profile.geometry().canonicalSrid()!=4326){issue(handoffId,sourceObjectId,null,"SPATIAL_POLICY_INVALID",List.of(),Map.of("canonicalSrid",profile.geometry().canonicalSrid()));return new Result(false,0,1);}Object geoJson=envelope.get("geoJson");String geometry=write(geoJson);Boolean valid=db.sql("select ST_IsValid(ST_SetSRID(ST_GeomFromGeoJSON(:g),4326))").param("g",geometry).query(Boolean.class).single();if(!valid){issue(handoffId,sourceObjectId,null,"SPATIAL_INVALID_GEOMETRY",List.of(),Map.of("sourceCrs",crs,"normalizationVersion",profile.geometry().normalizationVersion()));return new Result(false,0,1);}
    UUID geometryRevision=storeGeometry(handoffId,sourceObjectId,handoff,profile,geometry);int matched=0,review=0;for(var rule:profile.relationships()){List<Candidate> candidates=find(sourceObjectId,geometryRevision,rule);if(candidates.isEmpty()){if("QUARANTINE_RELATION".equals(rule.onNoMatch())){issue(handoffId,sourceObjectId,rule.relationIri(),"SPATIAL_NO_MATCH",List.of(),evidence(profile,rule));review++;}continue;}if(ambiguous(candidates,rule)){issue(handoffId,sourceObjectId,rule.relationIri(),"SPATIAL_MULTIPLE_MATCHES",candidates.stream().map(Candidate::id).toList(),evidence(profile,rule));review++;continue;}UUID target=candidates.getFirst().id();if(target.equals(sourceObjectId)&&!rule.selfLoopAllowed()){issue(handoffId,sourceObjectId,rule.relationIri(),"SELF_LOOP_NOT_ALLOWED",List.of(target),evidence(profile,rule));review++;continue;}writeEdge(handoffId,sourceObjectId,target,rule,geometryRevision,profile.policyRef(),candidates.getFirst().metric());matched++;}return new Result(true,matched,review);
  }
  private UUID storeGeometry(String handoff,UUID object,Map<String,Object> payload,UdpPorts.SpatialProfile profile,String geoJson){String hash=db.sql("select encode(digest(ST_AsEWKB(ST_SetSRID(ST_GeomFromGeoJSON(:g),4326)),'sha256'),'hex')").param("g",geoJson).query(String.class).single();List<UUID> old=db.sql("select geometry_revision_id from ouf_udp.urban_geometry where urban_object_id=:u and geometry_hash=:h and normalization_version=:n").param("u",object).param("h",hash).param("n",profile.geometry().normalizationVersion()).query(UUID.class).list();UUID id;if(old.isEmpty()){id=UUID.randomUUID();Map<String,Object> evidence=Map.of("handoffRef","handoff://"+handoff,"lineageRef",payload.get("lineageId"),"sourceCrs",profile.geometry().expectedSourceCrs(),"canonicalSrid",4326,"normalizationVersion",profile.geometry().normalizationVersion(),"contractRefs",payload.get("contractRefs"));db.sql("insert into ouf_udp.urban_geometry(geometry_revision_id,urban_object_id,handoff_id,geometry,geometry_hash,source_crs,canonical_srid,normalization_version,access_label,evidence_json) values(:i,:u,:h,ST_SetSRID(ST_GeomFromGeoJSON(:g),4326),:x,:s,4326,:n,:a,cast(:e as jsonb))").param("i",id).param("u",object).param("h",handoff).param("g",geoJson).param("x",hash).param("s",profile.geometry().expectedSourceCrs()).param("n",profile.geometry().normalizationVersion()).param("a",profile.geometry().accessLabel()).param("e",write(evidence)).update();}else id=old.getFirst();db.sql("insert into ouf_udp.urban_geometry_current(urban_object_id,geometry_revision_id) values(:u,:g) on conflict(urban_object_id) do update set geometry_revision_id=excluded.geometry_revision_id").param("u",object).param("g",id).update();return id;}
  private List<Candidate> find(UUID source,UUID geometry,UdpPorts.SpatialRelationshipRule r){String predicate=r.predicate();if("NEAREST".equals(predicate)&&r.maxDistanceMeters()==null)throw new IllegalArgumentException("UDP_SPATIAL_MAX_DISTANCE_REQUIRED");String condition=switch(predicate){case "INTERSECTS"->"ST_Intersects(s.geometry,t.geometry)";case "WITHIN"->"ST_Within(s.geometry,t.geometry)";case "CONTAINS"->"ST_Contains(s.geometry,t.geometry)";case "NEAREST"->"ST_DWithin(s.geometry::geography,t.geometry::geography,:distance)";case "OVERLAP_RATIO"->"ST_Area(ST_Intersection(s.geometry,t.geometry)::geography)/nullif(ST_Area(s.geometry::geography),0)>=:overlap";default->throw new IllegalArgumentException("UDP_SPATIAL_PREDICATE_UNSUPPORTED");};String sql="select o.urban_object_id,ST_Distance(s.geometry::geography,t.geometry::geography) metric from ouf_udp.urban_geometry s join ouf_udp.urban_geometry_current tc on true join ouf_udp.urban_geometry t on t.geometry_revision_id=tc.geometry_revision_id join ouf_udp.urban_object o on o.urban_object_id=tc.urban_object_id where s.geometry_revision_id=:g and o.canonical_type=:t and o.status='ACTIVE' and "+condition+" order by metric,o.urban_object_id";var spec=db.sql(sql).param("g",geometry).param("t",r.targetCanonicalType());if(sql.contains(":distance"))spec=spec.param("distance",r.maxDistanceMeters());if(sql.contains(":overlap")){if(r.minOverlapRatio()==null)throw new IllegalArgumentException("UDP_SPATIAL_MIN_OVERLAP_REQUIRED");spec=spec.param("overlap",r.minOverlapRatio());}return spec.query((rs,n)->new Candidate(rs.getObject("urban_object_id",UUID.class),rs.getDouble("metric"))).list();}
  private static boolean ambiguous(List<Candidate> c,UdpPorts.SpatialRelationshipRule r){if(c.size()==1)return false;if(!"NEAREST".equals(r.predicate())||r.rankingMarginMeters()==null)return true;return c.get(1).metric()-c.getFirst().metric()<r.rankingMarginMeters();}
  private void writeEdge(String handoff,UUID source,UUID target,UdpPorts.SpatialRelationshipRule rule,UUID geometry,String policy,double metric){UUID contribution=UUID.randomUUID();String sourceHash=hash(Map.of("geometryRevision",geometry,"target",target));Map<String,Object> provenance=Map.of("handoffRef","handoff://"+handoff,"geometryRevisionRef","geometry://"+geometry,"predicate",rule.predicate(),"policyRef",policy,"metricMeters",metric);db.sql("insert into ouf_udp.relationship_contribution(contribution_id,handoff_id,source_object_id,relation_iri,source_value,source_value_hash,strategy_ref,policy_ref,access_label,provenance_json) values(:i,:h,:s,:r,cast(:v as jsonb),:x,:t,:p,:a,cast(:e as jsonb)) on conflict(handoff_id,relation_iri,source_value_hash) do nothing").param("i",contribution).param("h",handoff).param("s",source).param("r",rule.relationIri()).param("v",write(Map.of("geometryRevision",geometry))).param("x",sourceHash).param("t",rule.predicate()).param("p",policy).param("a",rule.accessLabel()).param("e",write(provenance)).update();contribution=db.sql("select contribution_id from ouf_udp.relationship_contribution where handoff_id=:h and relation_iri=:r and source_value_hash=:x").param("h",handoff).param("r",rule.relationIri()).param("x",sourceHash).query(UUID.class).single();UUID relationship=UUID.nameUUIDFromBytes((source+"|"+rule.relationIri()+"|"+target).getBytes(StandardCharsets.UTF_8));db.sql("insert into ouf_udp.urban_relationship(relationship_id,source_object_id,relation_iri,target_object_id) values(:i,:s,:r,:t) on conflict(source_object_id,relation_iri,target_object_id) do nothing").param("i",relationship).param("s",source).param("r",rule.relationIri()).param("t",target).update();relationship=db.sql("select relationship_id from ouf_udp.urban_relationship where source_object_id=:s and relation_iri=:r and target_object_id=:t").param("s",source).param("r",rule.relationIri()).param("t",target).query(UUID.class).single();String evidenceHash=hash(Map.of("geometry",geometry,"target",target,"predicate",rule.predicate(),"metric",metric));List<UUID> old=db.sql("select relationship_revision_id from ouf_udp.relationship_revision where relationship_id=:r and evidence_hash=:h").param("r",relationship).param("h",evidenceHash).query(UUID.class).list();if(old.isEmpty()){UUID revision=UUID.randomUUID();long no=db.sql("select coalesce(max(revision_no),0)+1 from ouf_udp.relationship_revision where relationship_id=:r").param("r",relationship).query(Long.class).single();db.sql("insert into ouf_udp.relationship_revision(relationship_revision_id,relationship_id,revision_no,contribution_id,evidence_hash,resolution_evidence,access_label) values(:i,:r,:n,:c,:h,cast(:e as jsonb),:a)").param("i",revision).param("r",relationship).param("n",no).param("c",contribution).param("h",evidenceHash).param("e",write(provenance)).param("a",rule.accessLabel()).update();db.sql("update ouf_udp.urban_relationship set current_revision_id=:v where relationship_id=:r").param("v",revision).param("r",relationship).update();}}
  private void issue(String handoff,UUID source,String relation,String reason,List<UUID> candidates,Map<String,Object> evidence){db.sql("insert into ouf_udp.spatial_resolution_issue(issue_id,handoff_id,source_object_id,relation_iri,reason_code,candidate_refs,evidence_json) values(gen_random_uuid(),:h,:s,:r,:c,cast(:a as jsonb),cast(:e as jsonb)) on conflict do nothing").param("h",handoff).param("s",source).param("r",relation,Types.VARCHAR).param("c",reason).param("a",write(candidates.stream().map(x->"urban-object://"+x).toList())).param("e",write(evidence)).update();}
  private static Map<String,Object> evidence(UdpPorts.SpatialProfile p,UdpPorts.SpatialRelationshipRule r){Map<String,Object> e=new LinkedHashMap<>();e.put("policyRef",p.policyRef());e.put("predicate",r.predicate());e.put("sourceCrs",p.geometry().expectedSourceCrs());e.put("canonicalSrid",p.geometry().canonicalSrid());e.put("normalizationVersion",p.geometry().normalizationVersion());e.put("maxDistanceMeters",r.maxDistanceMeters());e.put("minOverlapRatio",r.minOverlapRatio());e.put("rankingMarginMeters",r.rankingMarginMeters());return e;}
  private String hash(Object value){try{return "sha256:"+HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(value)));}catch(Exception e){throw new IllegalStateException(e);}}
  private String write(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalArgumentException("UDP_JSON_INVALID",e);}}
  private record Candidate(UUID id,double metric){}
  public record Result(boolean geometryStored,int relationshipsMaterialized,int issuesOpened){}
}
